def generate_tree():
    values = random.sample(range(0, 201), random.randint(1, 200))

    # Construct a binary tree using a deque
    queue = deque()
    root = TreeNode(values[0])
    queue.append(root)

    i = 1
    while i < len(values):
        node = queue.popleft()

        left_value = values[i]
        left_child = TreeNode(left_value)
        node.left = left_child
        queue.append(left_child)
        i += 1

        if i < len(values):
            right_value = values[i]
            right_child = TreeNode(right_value)
            node.right = right_child
            queue.append(right_child)
            i += 1

    return root


