def serialize_tree(root):
    if root is None:
        return "[]"

    queue = [root]
    res = []
    while queue:
        node = queue.pop(0)
        if node is None:
            res.append('null')
            continue
        res.append(str(node.val))
        queue.append(node.left)
        queue.append(node.right)

    while res and res[-1] == 'null':
        res.pop()

    return '[' + ','.join(res) + ']'

