import random

def build_tree_with_parents(vals):
    """Build a tree where each node has a parent pointer. Returns list of nodes."""
    from collections import deque
    if not vals:
        return []
    nodes = [None] * len(vals)
    for i, v in enumerate(vals):
        nodes[i] = Node(v)
        nodes[i].parent = None  # Initialize parent to None for all nodes
    for i in range(len(nodes)):
        li, ri = 2*i+1, 2*i+2
        if li < len(nodes):
            nodes[i].left = nodes[li]
            nodes[li].parent = nodes[i]
        if ri < len(nodes):
            nodes[i].right = nodes[ri]
            nodes[ri].parent = nodes[i]
    return nodes

def lca_brute(p, q):
    """Compute LCA via ancestor sets."""
    ancestors = set()
    a = p
    while a:
        ancestors.add(id(a))
        a = a.parent
    b = q
    while b:
        if id(b) in ancestors:
            return b
        b = b.parent
    return None

