def _tree_to_code(node):
    if node is None:
        return "None"
    cls = type(node).__name__
    if hasattr(node, 'left') and hasattr(node, 'right'):
        l = _tree_to_code(node.left)
        r = _tree_to_code(node.right)
        if l == "None" and r == "None":
            return f"{cls}({node.val!r})"
        return f"{cls}({node.val!r}, {l}, {r})"
    return repr(node)

def _list_to_code(node):
    if node is None:
        return "None"
    cls = type(node).__name__
    parts = []
    curr = node
    while curr:
        parts.append(repr(curr.val))
        curr = curr.next
    result = "None"
    for v in reversed(parts):
        result = f"{cls}({v}, {result})"
    return result

def _add_node_methods(cls):
    import inspect
    try:
        params = list(inspect.signature(cls.__init__).parameters.keys())
    except Exception:
        params = []
    if 'left' in params or 'right' in params:
        def __repr__(self):
            return _tree_to_code(self)
        def __eq__(self, other):
            if other is None: return False
            return (type(self).__name__ == type(other).__name__ and
                    self.val == other.val and self.left == other.left and self.right == other.right)
        cls.__repr__ = __repr__
        cls.__eq__ = __eq__
        cls.__hash__ = lambda self: id(self)
    elif 'next' in params and 'val' in params:
        def __repr__(self):
            return _list_to_code(self)
        def __eq__(self, other):
            if other is None: return False
            return (type(self).__name__ == type(other).__name__ and
                    self.val == other.val and self.next == other.next)
        cls.__repr__ = __repr__
        cls.__eq__ = __eq__
        cls.__hash__ = lambda self: id(self)
    return cls

