import random

def build_bst(vals):
    """Build BST by insertion."""
    root = None
    for v in vals:
        root = bst_insert(root, v)
    return root

def bst_insert(root, val):
    if root is None:
        return TreeNode(val)
    if val < root.val:
        root.left = bst_insert(root.left, val)
    else:
        root.right = bst_insert(root.right, val)
    return root

def lca_bst(root, p_val, q_val):
    """LCA of BST using values."""
    while root:
        if p_val < root.val and q_val < root.val:
            root = root.left
        elif p_val > root.val and q_val > root.val:
            root = root.right
        else:
            return root
    return None

