def generate_bst():
    # Generate a sorted list of unique values
    nums = sorted(random.sample(range(1, 101), random.randint(2, 10)))

    # Convert the list of values into a binary search tree
    return convert_to_bst(nums, 0, len(nums) - 1)


def convert_to_bst(nums, left, right):
    if left > right:
        return None
    mid = (left + right) // 2
    root = TreeNode(nums[mid])
    root.left = convert_to_bst(nums, left, mid - 1)
    root.right = convert_to_bst(nums, mid + 1, right)
    return root


