    nodes = []
    for value in values:
        nodes.append(TreeNode(value))

    for i in range(num_nodes // 2):
        nodes[i].left = nodes[2 * i + 1]
        if 2 * i + 2 < num_nodes:
            nodes[i].right = nodes[2 * i + 2]

    return nodes[0]


def generate_random_node(root):
